SELECT

FROM TBL_FINANCING_APPROVAL

    DELETED = #{deleted}

        AND APPROVAL_ID = #{approvalId}


        AND FINANCING_TYPE = #{financingType}


        AND FINANCING_NO LIKE CONCAT('%', #{financingNo}, '%')


        AND COMPANY_ID = #{companyId}


        AND APPLICANT_ID = #{applicantId}


        AND APPROVAL_STATUS = #{approvalStatus}


        AND CURRENT_APPROVAL_NODE = #{currentApprovalNode}


        AND APPLICATION_TIME >= #{applicationTimeStart}


        AND APPLICATION_TIME <= #{applicationTimeEnd}


        AND (FINANCING_NO LIKE CONCAT('%', #{keyword}, '%')
        OR COMPANY_NAME LIKE CONCAT('%', #{keyword}, '%'))


ORDER BY APPLICATION_TIME DESC

